css:
.band{display:grid;grid-template-columns:repeat(3,1fr);gap:0}
.band>*{border-radius:0;box-shadow:none;border:0}
.band>*:nth-child(1){background:#fcd500}
.band>*:nth-child(2){background:#f5a8cd}
.band>*:nth-child(3){background:#26bfa5}
/* 1枚だけ縦2枚ぶんに */
.grid{display:grid;grid-template-columns:46% 27% 27%;grid-template-rows:1fr 1fr;gap:0}
.grid>:first-child{grid-row:1/3}
/* ラベルを面の中へ、罫は底1本 */
.step{border:0;display:flex;align-items:flex-end;justify-content:center;padding-bottom:12px}
.steps{border-bottom:1px solid #e0e6e9}
/* 見出しの地帯を写真に食わせる */
h2{display:inline-block;background:linear-gradient(90deg,#eef3c8,#d9efe8);padding:.5em 3em .5em 2.5em;border-radius:0;position:relative;z-index:0}
figure{position:relative;z-index:1}
